@import url('https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=Space+Grotesk:wght@400;500;600;700&display=swap');
:root{color-scheme:dark;--cyan:#5af8ff;--yellow:#ffe679;--white:#f5f6fa;--muted:#75808c;--mono:'Space Mono','DM Mono',monospace;--display:'Syne','Space Grotesk',sans-serif}*{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;overflow:hidden;background:#05070b;color:var(--white);font-family:var(--mono)}body{overscroll-behavior:none}button{font:inherit}#app{position:relative;width:100%;height:100%;min-height:500px;overflow:hidden;background:radial-gradient(ellipse at 75% 47%,#12202a 0,#091017 33%,#05070b 72%);isolation:isolate}#world,#flames{position:absolute;inset:0;width:100%;height:100%;display:block}#world{z-index:0}#flames{z-index:1;pointer-events:none;opacity:.82;transition:opacity 1s}#app.battle #flames{opacity:.08}.vignette,.noise{position:absolute;inset:0;pointer-events:none}.vignette{z-index:2;background:radial-gradient(ellipse at 50% 45%,transparent 35%,rgba(0,0,0,.24) 77%,rgba(0,0,0,.7) 130%)}.noise{z-index:3;opacity:.1;background-image:url("data:image/svg+xml,%3Csvg viewBox='0 0 180 180' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.8' numOctaves='4' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.22'/%3E%3C/svg%3E");mix-blend-mode:screen}.hud{position:absolute;z-index:5;left:clamp(20px,4vw,58px);right:clamp(20px,4vw,58px);top:clamp(18px,3.8vh,38px);display:flex;justify-content:space-between;align-items:center;font-size:9px;letter-spacing:.18em;color:#a6b0bd}.brand-mark{display:flex;align-items:center;gap:10px}.brand-dot{width:7px;height:7px;border-radius:50%;background:var(--cyan);box-shadow:0 0 12px var(--cyan)}.sound-toggle{display:flex;align-items:center;gap:9px;cursor:pointer;user-select:none;transition:color .2s}.sound-toggle:hover{color:white}.sound-bars{height:13px;display:flex;align-items:center;gap:2px}.sound-bars i{display:block;width:2px;height:4px;background:var(--cyan);border-radius:2px}.sound-bars i:nth-child(2){height:9px}.sound-bars i:nth-child(3){height:6px}.sound-toggle.on .sound-bars i{animation:soundwave .7s ease-in-out infinite alternate}.sound-toggle.on .sound-bars i:nth-child(2){animation-delay:.2s}.sound-toggle.on .sound-bars i:nth-child(3){animation-delay:.4s}@keyframes soundwave{to{height:12px}}.title-stack{position:absolute;z-index:4;left:clamp(25px,9vw,140px);top:clamp(112px,17vh,180px);width:min(55vw,700px);text-align:left;pointer-events:none}.eyebrow{font-size:clamp(8px,.75vw,10px);letter-spacing:.34em;color:#6b8992;margin:0 0 16px 7px;opacity:0;animation:fadeUp .8s .25s ease-out forwards}.title-main,.title-sub,.title-edition{font-family:var(--display);font-weight:800;margin:0;line-height:.83;letter-spacing:-.075em}.title-main{font-size:clamp(64px,12.2vw,168px);color:#e8ffff;text-shadow:0 0 9px rgba(90,248,255,.9),0 0 28px rgba(40,221,255,.75),0 0 75px rgba(0,209,255,.36);opacity:0;transform:translateY(-46px) scale(.93);animation:titleDrop 1.15s .42s cubic-bezier(.16,1,.3,1) forwards}.title-sub{font-size:clamp(35px,6.6vw,89px);color:var(--yellow);letter-spacing:-.065em;margin-top:12px;text-shadow:0 0 8px rgba(255,230,121,.7),0 0 34px rgba(255,193,78,.45);opacity:0;transform:translateX(-22px);animation:fadeSlide .85s 1.2s cubic-bezier(.16,1,.3,1) forwards}.title-edition{font-size:clamp(21px,3.65vw,49px);letter-spacing:.23em;margin:19px 0 0 5px;width:max-content;background:linear-gradient(90deg,#ff526d,#ffbc52,#faff68,#61f4a8,#58dfff,#9771ff,#ff67dc,#ff526d);background-size:300% 100%;color:transparent;background-clip:text;-webkit-background-clip:text;animation:rainbow 5s linear infinite,fadeSlide .8s 1.95s cubic-bezier(.16,1,.3,1) both;text-shadow:0 0 24px rgba(255,255,255,.12)}@keyframes rainbow{to{background-position:300% 0}}@keyframes titleDrop{0%{opacity:0;transform:translateY(-46px) scale(.93)}70%{opacity:1;transform:translateY(5px) scale(1.015)}100%{opacity:1;transform:translateY(0) scale(1)}}@keyframes fadeSlide{to{opacity:1;transform:translate(0)}}@keyframes fadeUp{to{opacity:1;transform:translateY(0)}}.intro-caption{position:absolute;z-index:4;left:clamp(26px,9vw,140px);top:clamp(360px,65vh,635px);display:flex;align-items:center;gap:13px;font-size:8px;letter-spacing:.16em;color:#72818a;opacity:0;animation:fadeUp .8s 2.4s forwards}.caption-line{display:inline-block;width:25px;height:1px;background:var(--cyan);box-shadow:0 0 8px var(--cyan)}.bottom-meta{position:absolute;z-index:4;left:clamp(20px,4vw,58px);right:clamp(20px,4vw,58px);bottom:clamp(18px,3.5vh,32px);display:flex;justify-content:space-between;font-size:8px;letter-spacing:.16em;color:#66737c;transition:opacity .4s}.ready-button{position:absolute;z-index:6;left:50%;bottom:clamp(42px,8vh,76px);width:min(252px,70vw);height:57px;transform:translate(-50%,35px);background:#030609;border:1px solid rgba(255,255,255,.85);color:white;display:flex;align-items:center;justify-content:center;gap:32px;letter-spacing:.34em;font-size:12px;cursor:pointer;opacity:0;pointer-events:none;box-shadow:0 0 0 1px rgba(90,248,255,.1),0 0 30px rgba(0,220,255,.09);transition:background .25s,color .25s,box-shadow .25s,transform .25s}.ready-button:before{content:'';position:absolute;inset:4px;border:1px solid rgba(255,255,255,.12);pointer-events:none}.ready-button b{font-size:17px;font-weight:400;color:var(--cyan);transition:transform .2s}.ready-button:hover{background:#eaffff;color:#05070b;box-shadow:0 0 28px rgba(90,248,255,.4)}.ready-button:hover b{transform:translateX(5px);color:#05070b}.ready-button.show{pointer-events:auto;animation:buttonRise .8s 0s cubic-bezier(.16,1,.3,1) forwards}@keyframes buttonRise{to{opacity:1;transform:translate(-50%,0)}}.battle-hud{position:absolute;inset:0;z-index:6;display:none;pointer-events:none}.battle-hud>*{pointer-events:auto}.battle-hud.active{display:block}.battle-topline{position:absolute;top:clamp(68px,10vh,105px);left:50%;transform:translateX(-50%);width:min(440px,74vw);display:flex;justify-content:space-between;align-items:end;text-align:center}.battle-topline>div{display:grid;gap:5px}.battle-topline strong{font-family:var(--display);font-size:18px;letter-spacing:.19em}.tiny-label{font-size:8px;letter-spacing:.22em;color:#7e8d97}.wave-readout strong{color:var(--cyan)}.boss-bar{position:absolute;top:clamp(126px,17vh,168px);left:50%;transform:translateX(-50%);width:min(420px,70vw);height:3px;background:#1d2730}.boss-bar span{display:block;width:100%;height:100%;background:linear-gradient(90deg,#75f9ff,#bb74ff);box-shadow:0 0 10px rgba(90,248,255,.7);transition:width .5s}.battle-status{position:absolute;top:clamp(148px,19vh,190px);left:50%;transform:translateX(-50%);width:min(430px,78vw);display:flex;justify-content:space-between;color:#cbd2d8;font-size:9px;letter-spacing:.09em}.turn-clock{color:var(--cyan)}.arena-frame{position:absolute;left:50%;top:51%;transform:translate(-50%,-50%);width:min(490px,80vw);height:min(240px,32vh);min-height:160px;border:2px solid #e8edf0;background:rgba(3,6,10,.66);box-shadow:0 0 0 1px rgba(90,248,255,.08),0 0 38px rgba(0,0,0,.55),inset 0 0 40px rgba(29,63,75,.22);overflow:hidden;touch-action:none}.arena-frame:before,.arena-frame:after{content:'';position:absolute;inset:7px;border:1px solid rgba(255,255,255,.045);pointer-events:none}.arena-glow{position:absolute;inset:0;background:radial-gradient(ellipse at 50% 100%,rgba(0,188,221,.09),transparent 65%)}.soul{position:absolute;left:50%;top:55%;transform:translate(-50%,-50%);font-family:Arial,sans-serif;font-size:26px;line-height:1;color:#ff3b4e;text-shadow:0 0 5px #ff1d38,0 0 16px #fc2144;z-index:3;user-select:none;touch-action:none;cursor:grab;filter:drop-shadow(0 1px 5px rgba(255,0,40,.65));transition:filter .15s}.soul.hurt{animation:soulHurt .28s}@keyframes soulHurt{50%{filter:brightness(3) drop-shadow(0 0 12px red);transform:translate(-50%,-50%) scale(1.4)}}.player-stats{position:absolute;left:50%;top:calc(51% + min(120px,16vh) + 17px);transform:translateX(-50%);width:min(490px,80vw);display:grid;grid-template-columns:1fr minmax(95px,1.3fr) auto;align-items:center;gap:12px;font-size:9px}.player-name{font-family:var(--display);letter-spacing:.08em;font-weight:700}.player-name span{margin-left:8px;color:#b1bac1;font-family:var(--mono);font-size:8px}.hp-track{height:11px;background:#643c32;position:relative}.hp-track span{height:100%;width:100%;display:block;background:linear-gradient(90deg,#ffe96d,#ffb23f);transition:width .25s}.hp-numbers{font-family:var(--display);font-weight:700;font-size:13px;color:#ffe676;white-space:nowrap}.hp-numbers span{font-family:var(--mono);font-size:8px;color:#c2c8ca;margin-left:4px}.battle-actions{position:absolute;bottom:clamp(36px,7vh,65px);left:50%;transform:translateX(-50%);width:min(590px,88vw);display:flex;justify-content:space-between;gap:clamp(7px,2vw,18px)}.action-button{height:45px;flex:1;background:rgba(3,6,10,.88);border:1px solid #d5d9d9;color:#ffe36e;display:flex;justify-content:center;align-items:center;gap:8px;font-family:var(--display);font-size:12px;font-weight:700;letter-spacing:.06em;cursor:pointer;transition:all .2s}.action-button:hover,.action-button.active{border-color:#ffe36e;color:#fff4b1;box-shadow:0 0 15px rgba(255,226,88,.13);transform:translateY(-2px)}.action-icon{font-size:16px}.touch-hint{position:absolute;left:50%;transform:translateX(-50%);bottom:16px;color:#6f7b84;font-size:7px;letter-spacing:.13em;white-space:nowrap}.touch-hint kbd{font-family:var(--mono);font-size:7px;color:#aab7bf;border:1px solid #38434b;padding:2px 3px;border-radius:2px;margin:0 2px}.restart-button{display:none;position:absolute;left:50%;top:calc(51% + 15px);transform:translate(-50%,-50%);padding:14px 22px;background:#05090c;border:1px solid var(--cyan);color:var(--cyan);font-size:10px;letter-spacing:.15em;cursor:pointer;box-shadow:0 0 20px #00d9ff30}.battle-hud.over .restart-button{display:block}.battle-hud.over .arena-frame{border-color:#ff7182}.toast{position:absolute;z-index:8;left:50%;top:38%;transform:translate(-50%,10px);padding:11px 16px;background:rgba(2,7,10,.92);border:1px solid rgba(90,248,255,.4);font-size:9px;letter-spacing:.08em;color:#d7faff;opacity:0;transition:.3s;pointer-events:none;white-space:nowrap}.toast.show{opacity:1;transform:translate(-50%,0)}.screen-flash{position:absolute;z-index:7;inset:0;background:#fff;opacity:0;pointer-events:none}.screen-flash.hit{animation:flash .2s}@keyframes flash{50%{opacity:.25}}#app.battle .title-stack,#app.battle .intro-caption,#app.battle .bottom-meta,#app.battle .ready-button{opacity:0;pointer-events:none;transition:opacity .5s}.battle-hud{opacity:0;transition:opacity .5s}.battle-hud.active{opacity:1}.battle-hud.over .battle-actions,.battle-hud.over .touch-hint{opacity:.3;pointer-events:none}
@media(max-width:700px){#app{min-height:520px}.title-stack{left:7vw;top:19vh;width:86vw}.title-main{font-size:clamp(62px,15vw,108px)}.title-sub{font-size:clamp(37px,9vw,64px);margin-top:11px}.title-edition{font-size:clamp(22px,6vw,38px);margin-top:15px}.eyebrow{margin-bottom:13px}.intro-caption{left:7vw;top:60vh;font-size:7px}.bottom-meta{font-size:7px}.hud{font-size:8px}.ready-button{bottom:8vh;height:53px}.battle-topline{top:72px}.boss-bar{top:127px}.battle-status{top:143px}.arena-frame{top:47%;width:min(490px,88vw);height:min(260px,31vh);min-height:165px}.player-stats{top:calc(47% + min(130px,15.5vh) + 14px);width:88vw;gap:8px}.battle-actions{bottom:clamp(50px,9vh,78px);width:90vw}.action-button{height:42px;font-size:10px;gap:4px}.action-icon{font-size:13px}.touch-hint{bottom:18px;font-size:6.5px}.touch-hint kbd{font-size:6px}.brand-mark{letter-spacing:.12em}.battle-topline strong{font-size:16px}}
@media(max-height:650px){.battle-topline{top:56px}.boss-bar{top:107px}.battle-status{top:123px}.arena-frame{top:49%;height:28vh;min-height:130px}.player-stats{top:calc(49% + 14vh + 14px)}.battle-actions{bottom:36px}.touch-hint{bottom:9px}.title-stack{top:14vh}.intro-caption{top:64vh}.ready-button{bottom:6vh}}

import * as THREE from 'three';

const app = document.querySelector('#app');
const world = document.querySelector('#world');
const flameCanvas = document.querySelector('#flames');
const flameCtx = flameCanvas.getContext('2d');
const readyButton = document.querySelector('#readyButton');
const battleHud = document.querySelector('#battleHud');
const arena = document.querySelector('.arena-frame');
const soulEl = document.querySelector('#soul');
const toast = document.querySelector('#toast');
const reducedMotion = matchMedia('(prefers-reduced-motion: reduce)').matches;

// A small, original, hand-built 3D skeleton scene keeps the game self-contained.
const renderer = new THREE.WebGLRenderer({ canvas: world, alpha: true, antialias: true, powerPreference: 'high-performance' });
renderer.setPixelRatio(Math.min(devicePixelRatio || 1, 1.8));
renderer.setClearColor(0x000000, 0);
renderer.outputColorSpace = THREE.SRGBColorSpace;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.15;
const scene = new THREE.Scene();
const camera = new THREE.OrthographicCamera(-8, 8, 6, -6, .1, 100);
camera.position.set(0, 0, 22);
camera.lookAt(0, 0, 0);
scene.add(new THREE.AmbientLight(0x9eb7c9, 1.5));
const keyLight = new THREE.DirectionalLight(0xdffaff, 3.5); keyLight.position.set(-5, 7, 9); scene.add(keyLight);
const rimLight = new THREE.PointLight(0x00dfff, 18, 18); rimLight.position.set(5, 2, 4); scene.add(rimLight);
const floorGlow = new THREE.PointLight(0x00c5e8, 11, 12); floorGlow.position.set(-4, -5, 3); scene.add(floorGlow);
const stars = new THREE.Group(); scene.add(stars);
const starMaterial = new THREE.MeshBasicMaterial({ color: 0x9befff, transparent: true, opacity: .7 });
for (let i = 0; i < 110; i++) {
  const dot = new THREE.Mesh(new THREE.SphereGeometry(Math.random() * .018 + .008, 6, 6), starMaterial);
  dot.position.set((Math.random() - .5) * 25, (Math.random() - .5) * 14, -4 - Math.random() * 8);
  stars.add(dot);
}
const mat = (color, roughness = .78, metalness = 0) => new THREE.MeshStandardMaterial({ color, roughness, metalness });
const coatMat = mat(0x222e43); const coatLight = mat(0x33445e); const dark = mat(0x10151d); const bone = mat(0xe9edf0, .52); const shoeMat = mat(0x11151c);
const black = new THREE.MeshBasicMaterial({ color: 0x03070b });
const cyan = new THREE.MeshStandardMaterial({ color: 0x8cffff, emissive: 0x00dfff, emissiveIntensity: 3.8, roughness: .2 });
const eyeAuraMat = new THREE.MeshBasicMaterial({ color: 0x00eaff, transparent: true, opacity: .17, side: THREE.DoubleSide, blending: THREE.AdditiveBlending, depthWrite: false });
const sans = new THREE.Group(); scene.add(sans);
const torso = new THREE.Group(); sans.add(torso);
function ellipsoid(parent, material, pos, scale, segments = 24) {
  const mesh = new THREE.Mesh(new THREE.SphereGeometry(1, segments, Math.max(12, segments >> 1)), material);
  mesh.position.set(...pos); mesh.scale.set(...scale); parent.add(mesh); return mesh;
}
function cylinderBetween(parent, material, a, b, radiusA, radiusB = radiusA, segments = 12) {
  const start = new THREE.Vector3(...a), end = new THREE.Vector3(...b), dir = end.clone().sub(start);
  const mesh = new THREE.Mesh(new THREE.CylinderGeometry(radiusB, radiusA, dir.length(), segments), material);
  mesh.position.copy(start.add(end).multiplyScalar(.5)); mesh.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir.normalize()); parent.add(mesh); return mesh;
}
// Hood and short, rounded skeleton body.
ellipsoid(torso, coatMat, [0, -.62, 0], [.72, .85, .49]);
ellipsoid(torso, coatLight, [-.44, -.48, .12], [.35, .43, .37]);
ellipsoid(torso, coatLight, [.44, -.48, .12], [.35, .43, .37]);
ellipsoid(torso, dark, [0, -1.11, .13], [.5, .28, .42]);
// zipper / drawstrings
cylinderBetween(torso, mat(0x97a8b7), [0, -.16, .493], [0, -1.04, .52], .018, .018, 8);
for (const x of [-.22, .22]) cylinderBetween(torso, mat(0xb9c5cc), [x, -.18, .45], [x * 1.15, -.62, .5], .014, .014, 8);
// tiny arms, hands and sneakers
for (const side of [-1, 1]) {
  cylinderBetween(torso, coatMat, [side * .59, -.35, .05], [side * .79, -.83, .13], .2, .17);
  ellipsoid(torso, bone, [side * .8, -.88, .18], [.18, .14, .16]);
  cylinderBetween(torso, dark, [side * .29, -1.18, 0], [side * .32, -1.52, .03], .17, .15);
  ellipsoid(torso, shoeMat, [side * .34, -1.58, .12], [.26, .14, .3]);
}
// Skull: oversized friendly skull silhouette with sculpted cheeks and jaw.
const head = new THREE.Group(); head.position.set(0, .83, .05); torso.add(head);
ellipsoid(head, bone, [0, 0, 0], [.83, .84, .64], 32);
ellipsoid(head, bone, [0, -.42, .12], [.59, .39, .53], 28);
ellipsoid(head, bone, [-.69, -.08, .02], [.22, .28, .38], 20);
ellipsoid(head, bone, [.69, -.08, .02], [.22, .28, .38], 20);
// eye sockets and the signature lit eye (front of the face is +Z)
ellipsoid(head, black, [-.31, .12, .548], [.23, .3, .11]);
ellipsoid(head, black, [.31, .12, .548], [.23, .3, .11]);
ellipsoid(head, cyan, [.33, .09, .66], [.10, .145, .045], 20);
ellipsoid(head, new THREE.MeshBasicMaterial({ color: 0xffffff }), [.345, .09, .704], [.035, .09, .025], 16);
const aura = new THREE.Mesh(new THREE.CircleGeometry(.42, 32), eyeAuraMat); aura.position.set(.32, .09, .57); head.add(aura);
const eyeLight = new THREE.PointLight(0x00dcff, 2.5, 2.8); eyeLight.position.set(.36, .12, 1); head.add(eyeLight);
// Nose and grin, built from fine, dark tubes over the jaw.
ellipsoid(head, mat(0xc8d1d5), [0, -.23, .62], [.055, .07, .04], 12);
const grinPts = [new THREE.Vector3(-.43, -.38, .56), new THREE.Vector3(-.3, -.43, .64), new THREE.Vector3(-.14, -.45, .66), new THREE.Vector3(0, -.44, .67), new THREE.Vector3(.16, -.45, .66), new THREE.Vector3(.31, -.42, .63), new THREE.Vector3(.43, -.37, .56)];
const grin = new THREE.Mesh(new THREE.TubeGeometry(new THREE.CatmullRomCurve3(grinPts), 24, .018, 5, false), mat(0x78838b)); head.add(grin);
for (let i = 0; i < 6; i++) {
  const x = -.31 + i * .125;
  cylinderBetween(head, mat(0x9ca7ac), [x, -.418, .64], [x, -.48, .63], .009, .009, 5);
}
// Floating cyan dust motes around the silhouette.
const motes = new THREE.Group(); scene.add(motes);
for (let i = 0; i < 16; i++) {
  const mote = new THREE.Mesh(new THREE.SphereGeometry(.025 + Math.random() * .025, 8, 6), new THREE.MeshBasicMaterial({ color: i % 3 ? 0x39eaff : 0xfadf71, transparent: true, opacity: .72 }));
  mote.userData = { phase: Math.random() * 6.28, radius: 1.3 + Math.random() * 2.6, speed: .3 + Math.random() * .6 };
  motes.add(mote);
}
const clock = new THREE.Clock();
let viewWidth = 16, viewHeight = 12, introStart = performance.now(), battleMode = false, battleTime = 0;
let flameW = 0, flameH = 0, flames = [];
function resize() {
  const w = innerWidth, h = innerHeight;
  renderer.setSize(w, h, false); viewHeight = 12; viewWidth = viewHeight * w / h;
  camera.left = -viewWidth / 2; camera.right = viewWidth / 2; camera.top = viewHeight / 2; camera.bottom = -viewHeight / 2; camera.updateProjectionMatrix();
  flameW = flameCanvas.width = Math.floor(w * Math.min(devicePixelRatio || 1, 1.5));
  flameH = flameCanvas.height = Math.floor(h * Math.min(devicePixelRatio || 1, 1.5));
  flameCanvas.style.width = `${w}px`; flameCanvas.style.height = `${h}px`;
  flames = Array.from({ length: Math.floor(w / 9) }, () => ({ x: Math.random() * flameW, y: flameH + Math.random() * flameH * .25, r: 12 + Math.random() * 45, life: Math.random(), drift: (Math.random() - .5) * .75 }));
}
addEventListener('resize', resize); resize();
function drawFlames(dt) {
  const ctx = flameCtx; ctx.clearRect(0, 0, flameW, flameH);
  const sx = flameW / innerWidth, sy = flameH / innerHeight;
  ctx.save(); ctx.scale(sx, sy); ctx.globalCompositeOperation = 'lighter';
  const base = innerHeight * .97;
  for (const f of flames) {
    f.life += dt * (.55 + Math.random() * .4); f.y -= dt * (80 + f.r * 3); f.x += f.drift + Math.sin(f.life * 5 + f.x) * .45;
    if (f.y < innerHeight * (.35 + Math.random() * .3) || f.life > 2.3) { f.y = base + Math.random() * 80; f.x = Math.random() * innerWidth; f.r = 10 + Math.random() * 49; f.life = 0; }
    const life = Math.max(0, 1 - f.life / 2.3), radius = f.r * (.4 + life * .75);
    const grad = ctx.createRadialGradient(f.x, f.y, 0, f.x, f.y, radius);
    grad.addColorStop(0, `rgba(218,255,255,${.22 * life})`); grad.addColorStop(.24, `rgba(0,238,255,${.18 * life})`); grad.addColorStop(1, 'rgba(0,159,255,0)');
    ctx.fillStyle = grad; ctx.beginPath(); ctx.arc(f.x, f.y, radius, 0, Math.PI * 2); ctx.fill();
  }
  const bed = ctx.createLinearGradient(0, innerHeight, 0, innerHeight * .57);
  bed.addColorStop(0, 'rgba(0,220,248,.22)'); bed.addColorStop(.28, 'rgba(0,183,240,.12)'); bed.addColorStop(1, 'rgba(0,130,220,0)'); ctx.fillStyle = bed; ctx.fillRect(0, innerHeight * .56, innerWidth, innerHeight * .44);
  ctx.restore();
}

