.blackout{position:absolute;inset:0;z-index:20;background:#000;opacity:0;visibility:hidden;pointer-events:none;transition:opacity .55s ease,visibility .55s}.blackout.cover{opacity:1;visibility:visible;pointer-events:auto;transition:opacity .55s ease}
.corridor-hud{position:absolute;z-index:5;inset:0 0 auto;display:none;align-items:center;justify-content:space-between;padding:clamp(18px,3.8vh,38px) clamp(20px,4vw,58px);pointer-events:none;color:#d9faff;text-shadow:0 0 12px #00dfff80;font-size:9px;letter-spacing:.2em}
.corridor-label{font-weight:700;color:#9befff}.corridor-prompt{color:#b4c3cb;font-size:8px;letter-spacing:.12em}
.mobile-controls{position:absolute;z-index:7;inset:auto 0 0;display:none;align-items:flex-end;justify-content:space-between;padding:0 max(6vw,env(safe-area-inset-left)) max(5vh,env(safe-area-inset-bottom)) max(6vw,env(safe-area-inset-left));pointer-events:none}
.joystick{width:clamp(94px,16vh,142px);height:clamp(94px,16vh,142px);position:relative;border-radius:50%;background:rgba(0,0,0,.34);border:1px solid rgba(255,255,255,.36);touch-action:none;pointer-events:auto;user-select:none;-webkit-user-select:none}
.joystick-ring{position:absolute;inset:17%;border:1px solid rgba(255,255,255,.18);border-radius:50%;pointer-events:none}
